 const newChat=()=>{const now=new Date().toISOString();const c:Conversation={id:crypto.randomUUID(),title:"New chat",messages:[],createdAt:now,updatedAt:now};setConversations(current=>[c,...current]);setActiveConversationId(c.id);setChatInput("");setTab("chat")};
 const renameChat=(id:string)=>{const current=conversations.find(c=>c.id===id);const title=window.prompt("Name this conversation",current?.title||"New chat");if(title?.trim())setConversations(items=>items.map(c=>c.id===id?{...c,title:title.trim()}:c))};
