 const send=async()=>{if(!chatInput.trim()||aiBusy||!activeConversationId)return;const conversationId=activeConversationId;const user:ChatMessage={id:crypto.randomUUID(),role:"user",content:chatInput.trim(),createdAt:new Date().toISOString()};const next=[...chat,user];setConversations(current=>current.map(c=>c.id===conversationId?{...c,messages:next,title:c.title==="New chat"?user.content.slice(0,42):c.title,updatedAt:new Date().toISOString()}:c));setChatInput("");setAiBusy(true);try{const r=await aiChat(next,model);const answer:ChatMessage={id:crypto.randomUUID(),role:"assistant",content:r.content||r.message||"No response returned.",createdAt:new Date().toISOString()};setConversations(current=>current.map(c=>c.id===conversationId?{...c,messages:[...c.messages,answer],updatedAt:new Date().toISOString()}:c))}catch(e){const answer:ChatMessage={id:crypto.randomUUID(),role:"assistant",content:e instanceof Error?e.message:"AI service unavailable. Configure the secure AI endpoint.",createdAt:new Date().toISOString()};setConversations(current=>current.map(c=>c.id===conversationId?{...c,messages:[...c.messages,answer],updatedAt:new Date().toISOString()}:c))}finally{setAiBusy(false)}};
