 const createWebsite=async()=>{if(!builderPrompt.trim())return;setBuilderBusy(true);setBuilderStatus("Generating a fast, responsive website…");try{const designId=crypto.randomUUID();const prompt="Act as a senior product designer and front-end engineer. Create a premium, responsive single-file HTML website or browser app with inline CSS and lightweight JavaScript, semantic accessible markup, and working core interactions. ORIGINALITY: invent a distinct visual identity specifically for this brief. Do not copy an existing site, app, brand, screenshot, or template. Do not reuse generic placeholder icons or repeat the same hero image across unrelated projects. Create project-specific CSS/SVG iconography, visual motifs, layout rhythm, palette, typography and image composition. Avoid simple palette swaps of familiar templates. Every visual should fit the audience and purpose. PREMIUM QUALITY: refined spacing, mobile-first responsiveness, accessible contrast, purposeful motion, polished focus states, useful alt text and realistic content. Avoid fake testimonials, dead controls, generic AI-looking imagery, and bloated code. Return ONLY complete HTML; no external libraries, lengthy explanations, placeholders, or embedded base64 data. PROJECT UNIQUENESS KEY: "+designId+" (creative cue only; do not display).\n\nUSER BRIEF:\n"+builderPrompt.trim();const r=await aiTool("code",prompt);let html=r.content||r.message||"";html=html.replace(/^\s*```(?:html)?\s*/i,"").replace(/\s*```\s*$/,"");if(!/<html[\s>]/i.test(html)||!/<body[\s>]/i.test(html))throw new Error("The AI did not return a complete HTML page. Try a more specific prompt.");setBuilderHtml(html);setBuilderStatus("Website generated. Preview it, add your images, then export or publish.");}catch(e){setBuilderStatus(e instanceof Error?e.message:"Website generation failed.");}finally{setBuilderBusy(false);}};
